/**
 * Native Claude Code "fallback" notice.
 *
 * Claude Code (2.1.x) understands a server-side fallback block in the SSE stream:
 *   content_block_start { index, content_block: { type: 'fallback', from: {model}, to: {model}, trigger: {type: 'refusal'} } }
 * and surfaces a UI notice ("<model>'s safeguards flagged this message ... This response was generated by
 * <to> instead. Your session model is unchanged.").
 *
 * Its wording is refusal-specific, so we ONLY emit it for security-filter fallbacks (never for quota/capacity).
 * Disable with config.fallbackNoticeBlock = false.
 */

import { config } from '../config.js';

export function isFallbackNoticeEnabled() {
    return config?.fallbackNoticeBlock !== false;
}

/**
 * Wrap an Anthropic-format event stream: right after message_start, inject a `fallback` block (index 0, closed)
 * and shift every later content-block index by +1 so the stream stays consistent.
 * @param {AsyncIterable<Object>} source
 * @param {string} fromModel - model whose filter triggered
 * @param {string} toModel - model actually serving the response
 */
export async function* withFallbackNotice(source, fromModel, toModel) {
    let injected = false;
    for await (const ev of source) {
        if (!injected && ev?.type === 'message_start') {
            injected = true;
            yield ev;
            yield {
                type: 'content_block_start',
                index: 0,
                content_block: {
                    type: 'fallback',
                    from: { model: fromModel },
                    to: { model: toModel },
                    trigger: { type: 'refusal' }
                }
            };
            yield { type: 'content_block_stop', index: 0 };
            continue;
        }
        if (injected && typeof ev?.index === 'number') {
            yield { ...ev, index: ev.index + 1 };
        } else {
            yield ev;
        }
    }
}
